TComm::~TComm()
{
    StopComm();          // releases handle / joins reader if still open
    delete pImpl_;
    pImpl_ = 0;
}

unsigned long __stdcall TComm::ReaderProc_(void* param)
{
#if defined(_WIN32)
    TComm::Impl* im = static_cast<TComm::Impl*>(param);
    char buf[1024];
    for (;;) {
        if (::InterlockedCompareExchange(&im->bStopReader, 1, 1) != 0)
            break;
        DWORD nRead = 0;
        BOOL ok = ::ReadFile(im->hFile, buf, (DWORD)sizeof(buf), &nRead, 0);
        if (::InterlockedCompareExchange(&im->bStopReader, 1, 1) != 0)
            break;
        if (ok && nRead > 0) {
            if (im->self->OnReceiveData) {
                // Post bytes to the closure (Sender, Buffer, len).
                im->self->OnReceiveData(im->self,
                                        static_cast<void*>(buf),
                                        static_cast<Word>(nRead));
            }
        } else if (!ok) {
            break;  // read failed (port lost / handle closed): stop the loop
        } else {
            if (im->evStop != 0) ::WaitForSingleObject(im->evStop, 1); else ::Sleep(1);   //AI(W906-TORQUE-COMM) 20260925: ok && nRead==0（閒置）—— 原本直接繞回去，吃滿一顆 CPU   //AI(W906-COMM-STOPFAST) 20261006: 同樣等一個計時器刻度，但 StopComm 一設停止事件就醒（原本 Sleep(1) 要睡滿 15.6 ms，StopComm 在主執行緒上空等，實測每次 12～16 ms）
        }
        // ok && nRead==0 (interval timeout): loop and re-check the stop flag.
    }
#else
    (void)param;
#endif
    return 0;
}

void TComm::SimInjectReceive(const void* pData, Word len)
{
    // Fire OnReceiveData exactly as the real reader thread would: a private
    // copy of the bytes + the length, with this component as Sender.
    if (!OnReceiveData)
        return;
    std::vector<char> buf;
    if (pData != 0 && len > 0)
        buf.assign(static_cast<const char*>(pData),
                   static_cast<const char*>(pData) + len);
    else
        buf.resize(0);
    void* p = buf.empty() ? static_cast<void*>(0) : static_cast<void*>(&buf[0]);
    OnReceiveData(this, p, len);
}

void TSerialPoll::QueueRx(int port, const void* buf, Word len)
{
    if (buf == 0 || len == 0)
        return;
    {
        webbridge::WbGuard g(rxMutex);
        rxQueue.push_back(std::make_pair(port, std::string(static_cast<const char*>(buf), static_cast<size_t>(len))));
    }
    if (mailbox)
        ::SetEvent(mailbox->WakeHandle(testercomm::kEngineSide));   // wake the TesterComm loop now
}

void TSerialPoll::DrainRx()
{
    std::vector<std::pair<int, std::string> > q;
    {
        webbridge::WbGuard g(rxMutex);
        q.swap(rxQueue);
    }
    for (size_t i = 0; i < q.size(); ++i)
    {
        std::string& d = q[i].second;
        const WORD n = static_cast<WORD>(d.size());
        d.push_back('\0');   // golden CommAMDReceiveData strlen()s the buffer and ignores BufferLength
        switch (q[i].first)
        {
        case kRxCommAMD:
            CommAMDReceiveData(CommAMD, &d[0], n);     // Main.dfm:1564 OnReceiveData = CommAMDReceiveData
            break;
        case kRxCommAMD2:
            CommAMDReceiveData(CommAMD2, &d[0], n);    // Main.dfm:1595 (same handler, Sender tells them apart)
            break;
        case kRxAuxTester:
            if (fRS232Main)
                fRS232Main->CommTesterReceiveData(fRS232Main->CommTester, &d[0], n);   // RS232.dfm:43
            break;
        default:
            break;
        }
        if (closeRequested)
            break;   // golden: the form is closing; later chunks are never delivered
    }
}
